yakit.AutoInitYakit()

target = cli.String("target", cli.setDefault("qq.com"), cli.setRequired(true))
depth = cli.Int("depth", cli.setDefault(3), cli.setHelp("递归深度，0表示不递归，1表示递归一层（二级域名），以此类推"))
wildcardToStop = cli.Bool("wildcard-to-stop", cli.setHelp("设置泛解析停止"))
notRecursive = cli.Bool("not-recursive", cli.setHelp("设置是否递归爆破？"))

cli.check()

if depth > 0 {
    notRecursive = false
}

res, err := subdomain.Scan(
    target, 
    subdomain.recursive(!notRecursive), 
    subdomain.wildcardToStop(wildcardToStop),
    subdomain.maxDepth(depth)
)

if err != nil {
    yakit.Error("构建子域名扫描失败：%v", err)
    die(err)
}

yakit.Info("开始处理子域名扫描，目标: %v, 递归深度: %v", target, depth)

// 初始化表格和状态卡片
yakit.EnableTable("涉及C段表", ["涉及C段", "域名数量"])
yakit.EnableTable("子域名表", ["Domain", "IP", "层级"])
yakit.StatusCard("扫描状态", "运行中")
yakit.StatusCard("当前层级", "N/A")
yakit.StatusCard("已发现域名", "0")
yakit.StatusCard("已保存域名", "0")
yakit.StatusCard("活跃C段数", "0")

outputTableCClass = func(network, count) {
    yakit.TableData("涉及C段表", {
        "涉及C段": network,
        "域名数量": count,
        "uuid": network
    })
}

outputTable = func(domain, ip, level) {
    yakit.TableData("子域名表", {
        "Domain": domain,
        "IP": ip,
        "层级": level,
        "uuid": domain
    })
}

count = 0
savedCount = 0
cClassCollector = make(map[string]int)
mux = sync.NewLock()

updateStatus = func() {
    mux.Lock()
    defer mux.Unlock()
    yakit.StatusCard("已发现域名", sprintf("%v", count))
    yakit.StatusCard("已保存域名", sprintf("%v", savedCount))
    yakit.StatusCard("活跃C段数", sprintf("%v", len(cClassCollector)))
}

swg = sync.NewSizedWaitGroup(40)

submitToDB = func(domain, ip, level) {
    swg.Add()
    go func{
        defer swg.Done()
        yakit.SaveDomain(domain, ip)
        mux.Lock()
        savedCount++
        mux.Unlock()
        updateStatus()
    }
}

// 计算域名层级的函数
calcDomainLevel = func(domain, baseDomain) {
    baseParts = str.Split(baseDomain, ".")
    domainParts = str.Split(domain, ".")
    
    if len(domainParts) <= len(baseParts) {
        return 0
    }
    return len(domainParts) - len(baseParts)
}

for result = range res {
    domain = result.Domain
    ip = result.IP
    
    // 实时计算域名层级
    currentLevel = calcDomainLevel(domain, target)
    yakit.StatusCard("当前层级", sprintf("%d级域名", currentLevel))
    
    // 输出带层级的日志
    yakit.Info("发现[%d级域名]: %s -> %s", currentLevel, domain, ip)
    
    // 更新计数器和表格
    mux.Lock()
    count++
    outputTable(domain, ip, currentLevel)
    mux.Unlock()
    updateStatus()
    
    // 处理C段信息
    if ip != "" {
        network = str.IPv4ToCClassNetwork(ip)~
        mux.Lock()
        if !cClassCollector.Has(network) {
            cClassCollector[network] = 0
        }
        cClassCollector[network]++
        cCount = cClassCollector[network]
        mux.Unlock()
        
        // 仅在新C段发现时更新表格
        if cCount == 1 {
            outputTableCClass(network, cCount)
        }
    }
    
    submitToDB(domain, ip, currentLevel)
}

swg.Wait()
yakit.StatusCard("扫描状态", "已完成")
yakit.Info("扫描完成! 共发现 %d 个子域名, %d 个活跃C段", count, len(cClassCollector))
